        test("unplanned endpoint zero send",()->{LiveSafety.Plan p=plan();try(LiveSafety.Ledger l=ledger(p)){rejects(()->l.send("document","document-L1","POST",LiveSafety.EMBED+"?key=secret",KEY,embedding("document","L1",p),(e,k,b)->{throw new AssertionError();},LiveRagRunner::vector));check(l.total==0);}});
        for(String f:Arrays.asList("outputDimensionality","taskType","content"))test("wire guard "+f,()->{LiveSafety.Plan p=plan();try(LiveSafety.Ledger l=ledger(p)){JsonObject body=embedding("document","L1",p);if(f.equals("outputDimensionality"))body.addProperty(f,3072);else if(f.equals("taskType"))body.addProperty(f,"RETRIEVAL_QUERY");else body.getAsJsonObject("content").getAsJsonArray("parts").get(0).getAsJsonObject().addProperty("text","unapproved content");rejects(()->l.send("document","document-L1","POST",p.endpoint("document"),KEY,body,(e,k,b)->{throw new AssertionError();},LiveRagRunner::vector));check(l.total==0);}});
        test("sanitized failure evidence no key/body/vector",()->{LiveSafety.Plan p=plan();try(LiveSafety.Ledger l=ledger(p)){rejects(()->send(l,p,(e,k,b)->{throw new IOException(KEY);}));String evidence=Files.readString(l.evidence().resolve("document-L1.result.json"));check(!evidence.contains(KEY)&&!evidence.contains("values")&&!evidence.contains("x-goog-api-key"));}});
        test("two OS processes exclusive claim",()->{Path dir=Files.createDirectory(base.resolve(UUID.randomUUID().toString())),p=dir.resolve("test-plan.json");Files.writeString(p,approvedFixture(fixture).toString(),StandardOpenOption.CREATE_NEW);Process a=child("--claim",dir,p),b=child("--claim",dir,p);check(a.waitFor(15,java.util.concurrent.TimeUnit.SECONDS)&&b.waitFor(15,java.util.concurrent.TimeUnit.SECONDS));String outputs=new String(a.getInputStream().readAllBytes(),StandardCharsets.UTF_8)+new String(b.getInputStream().readAllBytes(),StandardCharsets.UTF_8);check(outputs.contains("CLAIMED")&&outputs.contains("BLOCKED")&&a.exitValue()!=b.exitValue());});
        test("process interruption cannot resume unknown reserved request",()->{Path dir=Files.createDirectory(base.resolve(UUID.randomUUID().toString())),p=dir.resolve("test-plan.json");JsonObject plan=approvedFixture(fixture);Files.writeString(p,plan.toString(),StandardOpenOption.CREATE_NEW);Process child=child("--interrupt",dir,p);check(child.waitFor(15,java.util.concurrent.TimeUnit.SECONDS)&&child.exitValue()==17);Path evidence=dir.resolve(LiveSafety.str(plan,"planId")+".evidence");check(Files.size(evidence.resolve("document-L1.result.json"))==0&&Files.exists(evidence.resolve("01-document-L1.reserved.json")));rejects(()->new LiveSafety.Ledger(new LiveSafety.Plan(plan),dir,ms->{}));});
