        test("HTTP decoder chunked",()->check(SinglePostWire.read(new ByteArrayInputStream(LiveSafety.bytes("HTTP/1.1 200 OK\r\nTransfer-Encoding: chunked\r\n\r\n2\r\n{}\r\n0\r\n\r\n"))).body.equals("{}")));
