        test("string dimensionality zero send",()->{LiveSafety.Plan p=plan();try(LiveSafety.Ledger l=ledger(p)){JsonObject body=embedding("document","L1",p);body.addProperty("outputDimensionality","768");rejects(()->l.send("document","document-L1","POST",LiveSafety.EMBED,KEY,body,(e,k,b)->{throw new AssertionError();},LiveRagRunner::vector));check(l.total==0);}});
