        test("unknown deferral cannot append unsupported prose",()->{String safe="Dạ em chưa có tài liệu đã duyệt để xác nhận thông tin này. Anh/chị muốn tư vấn thêm về dịch vụ Internet không?";check(LiveRagRunner.unknownReplyAllowed(safe));check(!LiveRagRunner.unknownReplyAllowed(safe+" Dịch vụ vẫn cung cấp ở nước ngoài."));check(!LiveRagRunner.unknownReplyAllowed("Dạ em chưa xác nhận nhưng vẫn có cung cấp dịch vụ ở nước ngoài."));});
