                primaryBuilt[0]=buildRequestBody(Arrays.asList(ai.dto.ChatMessage.system(ai.consultation.ConsultationPrompt.SYSTEM),ai.dto.ChatMessage.user("Chào")),baseOpts,"gemini-3.8-flash");
                backupBuilt[0]=buildRequestBody(Arrays.asList(ai.dto.ChatMessage.system(ai.consultation.ConsultationPrompt.SYSTEM),ai.dto.ChatMessage.user("Chào")),backupOpts,"gemini-3.5-flash-lite");
